fixed.gegenbauer_z0_odd_n_hypercomb_probe:
import mpmath as mp
mp.mp.dps = 80

def try_eval(expr_name, f):
    try:
        val = f()
        if isinstance(val, mp.mpf):
            # try to detect exact zeros
            if val == 0:
                out = '0'
            else:
                out = float(val)
        else:
            out = str(val)
        probe(expr_name, out)
    except Exception as e:
        probe(expr_name, f"{type(e).__name__}: {e}")

try_eval('odd_n_1_a1_z0', lambda: mp.gegenbauer(1, 1, 0))
try_eval('odd_n_5_a15_z0', lambda: mp.gegenbauer(5, mp.mpf('1.5'), 0))
try_eval('odd_n_3_a2_z0', lambda: mp.gegenbauer(3, 2, 0))
try_eval('odd_n_3_a1_mpc0', lambda: mp.gegenbauer(3, 1, mp.mpc(0)))

try_eval('even_n_2_a1_z0', lambda: mp.gegenbauer(2, 1, 0))
try_eval('even_n_4_a15_z0', lambda: mp.gegenbauer(4, mp.mpf('1.5'), 0))
try_eval('nonint_n_2p5_a1_z0', lambda: mp.gegenbauer(mp.mpf('2.5'), 1, 0))

